class GymMember {String id;int fee,sessions;GymMember(String i,int f){if(i==null||i.trim().length()<4)throw new IllegalArgumentException();id=i;fee=f;}void checkIn(){sessions++;}} class PremiumMember extends GymMember{String trainer;PremiumMember(String i,int f,String t){super(i,f);trainer=t;}} public class GymEnrollment {public static void main(String[]a){GymMember m=new PremiumMember("MEM1",1000,"Riya");m.checkIn();System.out.println(m.sessions);}}
